// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createLink, pinLink, getLinks, deleteLink } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");


test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const pinnedOnly = "true";

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "Unorganized"
        },
        "description": "",
        "name": "skyramp-pin-lifecycle",
        "tags": [],
        "type": "url",
        "url": "https://example.com/skyramp-pin-lifecycle"
    }`;

    const linksPostResponse = await createLink(client, headers, linksPostRequestBody);
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    const linkId = getResponseValue(linksPostResponse, "response.id");
    const callerId = getResponseValue(linksPostResponse, "response.createdById");
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("skyramp-pin-lifecycle");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/skyramp-pin-lifecycle");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.description"), 'description').toBe("");
    expect(getResponseValue(linksPostResponse, "response.collection.name"), 'collection name').toBe("Unorganized");
    expect(linkId, 'link id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const pinPatchResponse = await pinLink(client, headers, linkId);
    expect(pinPatchResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(pinPatchResponse, "response.id"), 'pinned link id').toBe(linkId);
    expect(getResponseValue(pinPatchResponse, "response.name"), 'pinned link name').toBe("skyramp-pin-lifecycle");
    expect(getResponseValue(pinPatchResponse, "response.url"), 'pinned link url').toBe("https://example.com/skyramp-pin-lifecycle");
    expect(getResponseValue(pinPatchResponse, "response.pinnedBy.0.id"), 'pinnedBy first entry').toBe(callerId);
    expect(getResponseValue(pinPatchResponse, "response.pinnedBy.1"), 'pinnedBy second entry').toBeNull();
    expect(getResponseValue(pinPatchResponse, "response.updatedAt"), 'updatedAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const linksGetResponse = await getLinks(client, headers, pinnedOnly);
    expect(linksGetResponse.statusCode, 'status code').toBe(200);
    const pinnedLinks = getResponseValue(linksGetResponse, "response");
    expect(pinnedLinks.map((l: any) => l.id), 'pinned-only listing after pinning').toContain(linkId);
    expect(pinnedLinks.find((l: any) => l.id === linkId).pinnedBy[0].id, 'pinnedBy in pinned-only listing').toBe(callerId);

    const pinPatch1Response = await pinLink(client, headers, linkId);
    expect(pinPatch1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(pinPatch1Response, "response.id"), 'unpinned link id').toBe(linkId);
    expect(getResponseValue(pinPatch1Response, "response.name"), 'unpinned link name').toBe("skyramp-pin-lifecycle");
    expect(getResponseValue(pinPatch1Response, "response.pinnedBy.0"), 'pinnedBy after unpin').toBeNull();

    const linksGet1Response = await getLinks(client, headers, pinnedOnly);
    expect(linksGet1Response.statusCode, 'status code').toBe(200);
    const pinnedLinksAfterUnpin = getResponseValue(linksGet1Response, "response");
    expect(pinnedLinksAfterUnpin.filter((l: any) => l.id === linkId).length, 'entries for this link in pinned-only listing').toBe(0);
    expect(pinnedLinksAfterUnpin.map((l: any) => l.id), 'pinned-only listing after unpinning').not.toContain(linkId);

    const linksLinksDeleteResponse = await deleteLink(client, headers, linkId);
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link id').toBe(linkId);
    expect(getResponseValue(linksLinksDeleteResponse, "response.name"), 'deleted link name').toBe("skyramp-pin-lifecycle");
});
